// defaultMaxResponseBytes is the default cap on upstream response bodies.
// It is used by ReadAllLimited to prevent memory exhaustion (issue #365).
const defaultMaxResponseBytes = 64 << 20 // 64 MiB

// SLMClient talks to a local Ollama /api/chat endpoint and asks the small
// model to produce a routing decision. The HTTP layer is abstracted so
// tests can substitute a deterministic stub.
//
// SLMClient no longer maintains its own decision cache (issue #489). The
// planner-level SLMCache (slm_cache.go) is the sole caching layer and
// honours NEXUS_SLM_CACHE_TTL=0 as a true kill-switch. Previously the
// internal cache silently fell back to a 5-minute TTL when the configured
// value was non-positive, defeating the documented disable contract.
type SLMClient struct {
	BaseURL string        // e.g. "http://localhost:11434"
	Model   string        // e.g. "qwen3-coder:4b"
	Timeout time.Duration // per-call timeout (default 8s)
	Client  *http.Client

	// ConfidenceFloor / ConfidenceCeiling bound the neutral band for
	// judge-guided adaptive routing (issue #47). When the empirical
	// local confidence passed to DecideWithConfidence is below the floor
	// the system prompt is augmented with a frontier bias; above the
	// ceiling it gets a local bias; inside the band the request is
	// byte-for-byte identical to the pre-issue-47 path. Zero values fall
	// back to DefaultConfidenceFloor / DefaultConfidenceCeiling.
	ConfidenceFloor   float64
	ConfidenceCeiling float64
}

// NewSLMClient constructs a client. Pass nil for Client to use
// http.DefaultClient.
func NewSLMClient(baseURL, model string, timeout time.Duration, client *http.Client) *SLMClient {
	if client == nil {
		client = http.DefaultClient
	}
	return &SLMClient{
		BaseURL: baseURL,
		Model:   model,
		Timeout: timeout,
		Client:  client,
	}
}

// slmSystemPrompt is the static instruction we send to the routing SLM.
// Keeping it as a package var (not a config field) makes it trivial to grep
// and to snapshot in tests.
const slmSystemPrompt = `You are an intelligent routing assistant for a coding agent proxy. 
    Analyze the user's prompt. 
    - If it is a simple task (boilerplate, styling, small isolated functions), output {"route": "local"}. 
    - If it is a complex task (deep debugging, multi-file refactoring), output {"route": "frontier"}. 
    - If it requires extreme architectural deliberation and planning, output {"route": "fusion"}.
	Respond ONLY in valid JSON. No explanations.`

// negativeBiasNote is appended to slmSystemPrompt when empirical local
// confidence for the task category is below the floor. It nudges the SLM
// toward frontier without hard-overriding its judgement — the SLM may
// still pick local for a trivially simple prompt.
const negativeBiasNote = `

ADAPTIVE ROUTING CONTEXT: Historical quality evaluations show the LOCAL model has performed POORLY on tasks similar to this one. Strongly prefer {"route": "frontier"} unless the task is trivially simple.`

// positiveBiasNote is appended when empirical local confidence is above the
// ceiling: the local model has a strong track record on this kind of task,
// so favour it when the request is not clearly complex.
const positiveBiasNote = `

ADAPTIVE ROUTING CONTEXT: Historical quality evaluations show the LOCAL model handles tasks similar to this one WELL. Prefer {"route": "local"} when the task is not clearly complex.`

// Decide returns the routing decision for prompt. It is the neutral-path
// entry point: equivalent to DecideWithConfidence with NeutralConfidence,
// so the SLM request is byte-for-byte identical to the pre-issue-47
// behaviour. The fallback on any failure (transport, decode, parse,
// unknown value) is RouteFrontier — that is the safest default because it
// never silently drops a request to a non-existent local model.
func (c *SLMClient) Decide(ctx context.Context, prompt string) (Route, error) {
	return c.DecideWithConfidence(ctx, prompt, NeutralConfidence)
}

// DecideWithConfidence is Decide augmented with the empirical local
// confidence signal (issue #47). confidence is a 0.0..1.0 estimate of how
// well the local model performs on prompts like this one, derived from
// historical judge scores (see ConfidenceStore). Below the floor the
// system prompt gains a frontier bias; above the ceiling a local bias;
// inside the neutral band the request is unchanged from Decide.
func (c *SLMClient) DecideWithConfidence(ctx context.Context, prompt string, confidence float64) (Route, error) {
	return c.decide(ctx, prompt, c.systemPromptFor(confidence))
}

// systemPromptFor returns the SLM system prompt for the given confidence,
// applying the floor/ceiling bias notes. It is separated out so tests can
// assert the exact augmentation without an HTTP round-trip.
func (c *SLMClient) systemPromptFor(confidence float64) string {
	floor := c.ConfidenceFloor
	if floor <= 0 {
		floor = DefaultConfidenceFloor
	}
	ceiling := c.ConfidenceCeiling
	if ceiling <= 0 {
		ceiling = DefaultConfidenceCeiling
	}
	switch {
	case confidence < floor:
		return slmSystemPrompt + negativeBiasNote
	case confidence > ceiling:
		return slmSystemPrompt + positiveBiasNote
	default:
		return slmSystemPrompt
	}
}

// decide performs the HTTP round-trip with the supplied system prompt.
// The planner-level SLMCache (slm_cache.go) is the sole caching layer;
// SLMClient itself is cache-free (issue #489).
func (c *SLMClient) decide(ctx context.Context, prompt, systemPrompt string) (Route, error) {
	payload, _ := json.Marshal(map[string]interface{}{
		"model": c.Model,
		"messages": []map[string]string{
			{"role": "system", "content": systemPrompt},
			{"role": "user", "content": prompt},
		},
		"format":  "json",
		"stream":  false,
		"options": map[string]float64{"temperature": 0.1},
	})

	timeout := c.Timeout
	if timeout <= 0 {
		timeout = 8 * time.Second
	}
	cctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	req, err := http.NewRequestWithContext(cctx, http.MethodPost,
		c.BaseURL+"/api/chat", bytes.NewReader(payload))
	if err != nil {
		return RouteFrontier, err
	}
	req.Header.Set("Content-Type", "application/json")

	resp, err := c.Client.Do(req)
	if err != nil {
		return RouteFrontier, err
	}
	defer resp.Body.Close()

	body, err := ioutils.ReadAllLimited(resp.Body, defaultMaxResponseBytes)
	if err != nil {
		return RouteFrontier, err
	}
	if resp.StatusCode != http.StatusOK {
		return RouteFrontier, fmt.Errorf("slm: status %d: %s", resp.StatusCode, body)
	}

	var raw struct {
		Message struct {
			Content string `json:"content"`
		} `json:"message"`
	}
	if err := json.Unmarshal(body, &raw); err != nil {
		return RouteFrontier, fmt.Errorf("slm: decode: %w", err)
	}
	content := strings.TrimSpace(raw.Message.Content)
	if content == "" {
		return RouteFrontier, errors.New("slm: empty content")
	}
	decision, err := parseSLMDecision(content)
	if err != nil {
		return RouteFrontier, err
	}

	route := Route(strings.ToLower(decision.Route))
	if route != RouteLocal && route != RouteFusion {
		route = RouteFrontier
	}

	return route, nil
}

// slmDecision is the parsed route-decision object returned by the routing
// SLM. The model is instructed to emit {"route":"local|frontier|fusion"},
// but it frequently wraps that in markdown fences or prose (issue #79).
// parseSLMDecision below tolerates those shapes so a usable decision is
// not discarded just because of formatting noise.
type slmDecision struct {
	Route string `json:"route"`
}

// parseSLMDecision extracts the route-decision JSON object from the SLM's
// raw response content. It tolerates three common SLM output shapes:
//  1. Bare JSON object: {"route":"local"}
//  2. Markdown-fenced JSON: ```json\n{"route":"local"}\n```
//  3. Prose before/after the first JSON object: Here: {"route":"local"} !
//
// It returns an error only when no valid JSON object can be found, so the
// caller (decide) can fall back to RouteFrontier — the safe default. The
// first balanced JSON object wins: if there are multiple objects only the
// first is considered, so ambiguous/conflicting responses do not silently
// pick a later object (issue #79).
//
// Defaults preserved for the caller: an unspecified or unknown route still
// resolves to RouteFrontier unless the object explicitly names local or
// fusion; confidence clamping and task-type defaults live in the planner
// and are untouched here.
func parseSLMDecision(content string) (slmDecision, error) {
	var d slmDecision
	content = strings.TrimSpace(content)

	// 1. Fast path: the whole content is a bare JSON object.
	if err := json.Unmarshal([]byte(content), &d); err == nil {
		return d, nil
	}

	// 2. Markdown-fenced JSON block (```json ... ``` or ``` ... ```).
	if fenced := extractFencedJSON(content); fenced != "" {
		if err := json.Unmarshal([]byte(fenced), &d); err == nil {
			return d, nil
		}
	}

	// 3. First balanced {...} substring, tolerating prose wrappers and
	// braces that appear inside JSON string literals.
	if obj := extractFirstJSONObject(content); obj != "" {
		if err := json.Unmarshal([]byte(obj), &d); err == nil {
			return d, nil
		}
	}

	return slmDecision{}, fmt.Errorf("slm: no parseable JSON decision in %q", content)
}

// extractFencedJSON returns the trimmed contents of the first markdown
// fenced code block in content, preferring a ```json opener and falling
// back to a bare ``` opener. It returns "" when no complete fenced block
// is present. Matching on the opener is case-insensitive so ```JSON and
// ```Json also work.
func extractFencedJSON(content string) string {
	lower := strings.ToLower(content)
	for _, opener := range []string{"```json", "```"} {
		idx := strings.Index(lower, opener)
		if idx < 0 {
			continue
		}
		start := idx + len(opener)
		// Skip a single trailing newline immediately after the opener so
		// it is not treated as part of the JSON payload.
		if rest := content[start:]; strings.HasPrefix(rest, "\r\n") {
			start += 2
		} else if strings.HasPrefix(rest, "\n") {
			start++
		}
		if start > len(content) {
			continue
		}
		end := strings.Index(content[start:], "```")
		if end < 0 {
			continue
		}
		return strings.TrimSpace(content[start : start+end])
	}
	return ""
}

// extractFirstJSONObject returns the first brace-balanced JSON object
// substring of content, starting at the first '{'. It is string-literal
// aware so braces that appear inside JSON string values do not affect
// balancing. It returns "" when content has no '{' or the braces never
// balance to zero.
func extractFirstJSONObject(content string) string {
	start := strings.IndexByte(content, '{')
	if start < 0 {
		return ""
	}
	depth := 0
	inString := false
	escaped := false
	for i := start; i < len(content); i++ {
		c := content[i]
		if escaped {
			escaped = false
			continue
		}
		if inString {
			switch c {
			case '\\':
				escaped = true
			case '"':
				inString = false
			}
			continue
		}
		switch c {
		case '"':
			inString = true
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				return content[start : i+1]
			}
		}
	}
	return ""
}

// HTTPPoster is the minimal interface SLMClient needs from an http.Client.
// It exists so tests can swap in fakes without depending on *http.Client.
type HTTPPoster interface {
	Do(req *http.Request) (*http.Response, error)
}

package router

// confidence.go closes the feedback loop between the async LLM-as-a-judge
// evaluator (internal/judge, issue #15) and the routing decision (issue #47).
//
// The judge scores ~10% of local-route responses on a 1..5 scale. Those
// scores were previously fire-and-forget. This file introduces a
// ConfidenceStore that aggregates historical judge scores by task
// category and exposes a single "how well does local do on this kind of
// task?" signal (0.0..1.0). The SLM router (slm.go) consumes that signal
// via DecideWithConfidence and nudges its system prompt toward frontier
// (low confidence) or local (high confidence).
//
// Dependency direction: internal/router does NOT import internal/judge.
// cmd/nexus/main.go owns both packages and bridges JudgeScore -> RecordOutcome.
// The confidence store lives here so the handler can call it without pulling
// in the judge package (the AGENTS.md hot-path dependency rule).

// NeutralConfidence is the confidence value that produces routing behaviour
// byte-for-byte identical to the pre-issue-47 path: no system-prompt
// augmentation. It is returned whenever there is insufficient data, the
// judge is disabled, or a query fails. 0.5 sits inside the default
// [floor, ceiling] band so the SLM request is unchanged.
const NeutralConfidence = 0.5

// Default confidence thresholds. When empirical local confidence for a
// category drops below the floor the SLM is biased toward frontier; above
// the ceiling it is biased toward local; inside the band the request is
// unchanged. Operators override via NEXUS_ROUTING_CONFIDENCE_FLOOR /
// NEXUS_ROUTING_CONFIDENCE_CEILING.
const (
	DefaultConfidenceFloor   = 0.4
	DefaultConfidenceCeiling = 0.85
)

// DefaultConfidenceMinSamples is the minimum number of judged outcomes a
// category needs before LocalConfidence reports anything other than
// NeutralConfidence. Below this the store returns 0.5 so routing is
// identical to today.
const DefaultConfidenceMinSamples = 5

// DefaultSuccessScore is the judge score (1..5) at or above which a local
// outcome is counted as "acceptable quality" when computing confidence.
// A 3 means "usable"; scores of 1..2 count as failures. This is a package
// constant rather than a config knob because the 1..5 scale is fixed by
// the judge's system prompt.
const DefaultSuccessScore = 3

// Category constants are the fixed set of task buckets Categorize emits.
// They mirror the DSL keyword spirit in dsl.go but cover the broader space
// the judge scores against.
const (
	CategoryCSS           = "css"
	CategoryRefactoring   = "refactoring"
	CategoryDebugging     = "debugging"
	CategoryTesting       = "testing"
	CategorySecurity      = "security"
	CategoryData          = "data"
	CategoryArchitecture  = "architecture"
	CategoryBoilerplate   = "boilerplate"
	CategoryDocumentation = "documentation"
	CategoryOther         = "other"
)

// ConfidenceStore aggregates historical judge outcomes by task category and
// answers "for prompts like this, does the local model deliver acceptable
// quality?".
//
// Implementations must be safe for concurrent use: RecordOutcome is called
// from the judge worker pool while LocalConfidence is called from request
// goroutines.
type ConfidenceStore interface {
	// RecordOutcome persists one judged outcome. route is the route that
	// produced the scored output (only RouteLocal outcomes influence
	// LocalConfidence). judgeScore is the 1..5 judge rating; scores
	// outside that range are ignored. An empty category returns an error
	// so upstream callers that fail to categorize a prompt are surfaced
	// rather than silently polluting the "other" bucket (issue #591).
	RecordOutcome(category string, route Route, judgeScore int) error

	// LocalConfidence returns the fraction of recent local outcomes for
	// category that scored acceptably (0.0..1.0). It returns
	// NeutralConfidence (0.5) when there is insufficient data so the
	// caller's routing is unchanged.
	LocalConfidence(category string) float64
}

// categoryKeywords maps each category to the substrings that select it.
// Order matters: earlier entries win when a prompt matches several
// categories, so the list runs from most-specific/most-complex
// (architecture, debugging) to least (documentation) before falling
// through to "other". Keywords are matched against the ASCII-lowercased
// prompt using the same cheap contains helpers as dsl.go.
var categoryKeywords = []struct {
	category string
	keywords []string
}{
	{CategoryArchitecture, []string{
		"architecture", "architectural", "system design", "design pattern",
		"microservice", "scalability", "distributed system", "high-level design",
	}},
	{CategoryDebugging, []string{
		"debug", "bug", "stack trace", "stacktrace", "traceback", "exception",
		"panic", "segfault", "crash", "error message", "why does", "not working",
		"fails", "failing", "broken",
	}},
	{CategoryTesting, []string{
		"test", "unit test", "integration test", "generate tests", "test case",
		"mock", "fixture", "coverage", "benchmark", "assert", "pytest", "jest",
	}},
	{CategorySecurity, []string{
		"security scan", "vulnerability", "injection", "xss", "csrf", "sanitize",
		"auth check", "owasp", "cve", "exploit", "pen test", "sast", "hardening",
	}},
	{CategoryData, []string{
		"sql query", "database", "migration", "schema", "query optimization",
		"parse json", "data model", "etl", "analytics", "pipeline",
	}},
	{CategoryRefactoring, []string{
		"refactor", "restructure", "extract method", "rename", "clean up",
		"cleanup", "simplify", "deduplicate", "move method", "reorganize",
	}},
	{CategoryCSS, []string{
		"css", "tailwind", "flexbox", "stylesheet", "styling", "responsive",
		"media query", "padding", "margin", "layout", "scss", "sass",
	}},
	{CategoryBoilerplate, []string{
		"boilerplate", "scaffold", "template", "getter", "setter", "crud",
		"skeleton", "stub", "starter",
	}},
	{CategoryDocumentation, []string{
		"docstring", "documentation", "document ", "readme", "comment",
		"explain", "javadoc", "godoc", "changelog",
	}},
}

// Categorize buckets prompt into one of the fixed Category* constants using
// a lightweight keyword classifier. It never calls out to an embedding
// model — it is a pure, cheap function on the prompt text so it is safe to
// call on the request hot path. Unmatched prompts fall through to
// CategoryOther.
func Categorize(prompt string) string {
	lower := toUnicodeLower(prompt)
	for _, group := range categoryKeywords {
		for _, kw := range group.keywords {
			if stringsContains(lower, kw) {
				return group.category
			}
		}
	}
	return CategoryOther
}

package router

import (
	"context"
	"database/sql"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sync"
	"time"

	// Pure-Go SQLite driver (no CGo). The same driver backs
	// internal/metrics; importing it here registers the "sqlite"
	// driver name. See modernc.org/sqlite.
	_ "modernc.org/sqlite"
)

// confidenceSchema is the v1 schema for the routing-confidence table.
// One row per judged local outcome. The index on (category, timestamp)
// keeps the sliding-window aggregate cheap — it is the only read pattern.
const confidenceSchema = `
CREATE TABLE IF NOT EXISTS routing_outcomes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    category  TEXT NOT NULL,
    route     TEXT NOT NULL,
    score     INTEGER NOT NULL,
    timestamp DATETIME NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_routing_outcomes_cat_ts
    ON routing_outcomes(category, timestamp);
`

const insertOutcomeSQL = `INSERT INTO routing_outcomes
    (category, route, score, timestamp) VALUES (?, ?, ?, ?)`

// confidenceQuerySQL aggregates the fraction of recent local outcomes for
// a category that scored at or above the success threshold. COUNT(*) is
// returned alongside so the caller can enforce the minimum-samples gate.
const confidenceQuerySQL = `
SELECT
    COUNT(*),
    COALESCE(AVG(CASE WHEN score >= ? THEN 1.0 ELSE 0.0 END), 0)
FROM routing_outcomes
WHERE category = ? AND route = ? AND timestamp > ?`

// confidenceOpTimeout bounds a single DB op. Aggregates over the small
// indexed table finish in microseconds; the timeout only guards a
// pathological disk stall so RecordOutcome / LocalConfidence never pin a
// goroutine.
const confidenceOpTimeout = 5 * time.Second

// SQLiteConfidenceStore is the production ConfidenceStore. Writes and reads
// are synchronous against a single-connection *sql.DB — the volume is low
// (only ~10% of local requests are judged) so a background drain goroutine
// is unnecessary. All exported methods are safe for concurrent use.
//
// The store degrades gracefully: any DB error on RecordOutcome is logged
// and dropped (the outcome is best-effort telemetry), and any error on
// LocalConfidence returns NeutralConfidence so routing falls back to the
// pre-issue-47 behaviour.
type SQLiteConfidenceStore struct {
	db           *sql.DB
	path         string
	successScore int
	minSamples   int
	window       time.Duration

	closeOnce sync.Once
	closeErr  error
}

// ConfidenceConfig tunes a SQLiteConfidenceStore. Zero values get safe
// defaults applied by OpenConfidenceStore.
type ConfidenceConfig struct {
	// Path is the on-disk SQLite database. ":memory:" is allowed for
	// tests; an empty path is rejected.
	Path string
	// SuccessScore is the judge score (1..5) at/above which an outcome
	// counts as a success. Defaults to DefaultSuccessScore.
	SuccessScore int
	// MinSamples is the minimum recent outcomes a category needs before
	// LocalConfidence reports a non-neutral value. Defaults to
	// DefaultConfidenceMinSamples.
	MinSamples int
	// Window is the sliding window; outcomes older than now-Window are
	// ignored. Defaults to 7 days.
	Window time.Duration
}

func (c *ConfidenceConfig) applyDefaults() {
	if c.SuccessScore <= 0 {
		c.SuccessScore = DefaultSuccessScore
	}
	if c.MinSamples <= 0 {
		c.MinSamples = DefaultConfidenceMinSamples
	}
	if c.Window <= 0 {
		c.Window = 168 * time.Hour
	}
}

// OpenConfidenceStore opens (creating on demand) the SQLite database at
// cfg.Path and returns a ready ConfidenceStore. The parent directory is
// created for on-disk paths. An empty path is rejected.
func OpenConfidenceStore(cfg ConfidenceConfig) (*SQLiteConfidenceStore, error) {
	if cfg.Path == "" {
		return nil, fmt.Errorf("router: empty confidence db path")
	}
	cfg.applyDefaults()

	if cfg.Path != ":memory:" {
		if dir := filepath.Dir(cfg.Path); dir != "" && dir != "." {
			if err := os.MkdirAll(dir, 0o755); err != nil {
				return nil, fmt.Errorf("router: mkdir %q: %w", dir, err)
			}
		}
	}

	db, err := sql.Open("sqlite", confidenceDSN(cfg.Path))
	if err != nil {
		return nil, fmt.Errorf("router: open confidence db %q: %w", cfg.Path, err)
	}
	// Single writer connection keeps SQLite happy without a dedicated
	// drain goroutine; WAL (see DSN) still lets the read path proceed.
	db.SetMaxOpenConns(1)
	db.SetMaxIdleConns(1)

	if err := db.Ping(); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("router: ping confidence db %q: %w", cfg.Path, err)
	}
	if _, err := db.ExecContext(context.Background(), confidenceSchema); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("router: create confidence schema: %w", err)
	}

	return &SQLiteConfidenceStore{
		db:           db,
		path:         cfg.Path,
		successScore: cfg.SuccessScore,
		minSamples:   cfg.MinSamples,
		window:       cfg.Window,
	}, nil
}

// confidenceDSN mirrors the metrics store's DSN: WAL journalling for
// concurrent readers, a bounded busy timeout, and NORMAL synchronous
// mode (this is best-effort telemetry, not durable accounting).
func confidenceDSN(path string) string {
	if path == ":memory:" {
		return "file::memory:?mode=memory&cache=shared"
	}
	return fmt.Sprintf(
		"file:%s?mode=rwc&_pragma=journal_mode(WAL)&_pragma=busy_timeout(5000)&_pragma=synchronous(NORMAL)",
		path,
	)
}

// Path returns the on-disk path the store was opened with.
func (s *SQLiteConfidenceStore) Path() string { return s.path }

// RecordOutcome implements ConfidenceStore. Best-effort: DB errors are
// logged and returned so the caller can decide. Scores outside the 1..5
// judge range are ignored (return nil) so a parse-failure JudgeScore
// (Score == 0) never skews the aggregate. An empty category is rejected
// with an error instead of being silently coerced to CategoryOther so
// upstream RecordOutcome bugs are visible (issue #591).
func (s *SQLiteConfidenceStore) RecordOutcome(category string, route Route, judgeScore int) error {
	return s.recordAt(category, route, judgeScore, time.Now().UTC())
}

// recordAt is RecordOutcome with an explicit timestamp. It exists so tests
// can seed old rows and exercise the sliding-window expiry path.
func (s *SQLiteConfidenceStore) recordAt(category string, route Route, judgeScore int, ts time.Time) error {
	if s == nil || s.db == nil {
		return nil
	}
	if category == "" {
		return fmt.Errorf("router: empty category in recordAt (caller failed to categorize the prompt)")
	}
	if judgeScore < 1 || judgeScore > 5 {
		return nil
	}
	ctx, cancel := context.WithTimeout(context.Background(), confidenceOpTimeout)
	defer cancel()
	if _, err := s.db.ExecContext(ctx, insertOutcomeSQL,
		category, string(route), judgeScore, ts.UTC()); err != nil {
		slog.Warn("confidence: record outcome",
			slog.String("category", category),
			slog.String("route", string(route)),
			slog.Any("err", err),
		)
		return err
	}
	return nil
}

// LocalConfidence implements ConfidenceStore. Returns NeutralConfidence
// when fewer than minSamples recent local outcomes exist for the category
// or when the query fails.
func (s *SQLiteConfidenceStore) LocalConfidence(category string) float64 {
	if s == nil || s.db == nil {
		return NeutralConfidence
	}
	if category == "" {
		category = CategoryOther
	}
	cutoff := time.Now().UTC().Add(-s.window)

	ctx, cancel := context.WithTimeout(context.Background(), confidenceOpTimeout)
	defer cancel()

	var (
		count int
		frac  float64
	)
	row := s.db.QueryRowContext(ctx, confidenceQuerySQL,
		s.successScore, category, string(RouteLocal), cutoff)
	if err := row.Scan(&count, &frac); err != nil {
		slog.Warn("confidence: query",
			slog.String("category", category),
			slog.Any("err", err),
		)
		return NeutralConfidence
	}
	if count < s.minSamples {
		return NeutralConfidence
	}
	return frac
}

// CategoryStats holds the raw aggregate for one task category in the
// sliding window. It is the unfiltered view used by the stats CLI —
// the minSamples gate that LocalConfidence applies internally is NOT
// enforced here so operators can see whether a category has any data
// at all.
type CategoryStats struct {
	Category   string
	Samples    int
	Confidence float64 // fraction of samples scoring >= successScore; 0 if no samples
}

// WindowStats returns per-category aggregates for every fixed Category*
// constant in the sliding window. Empty categories (no rows) are returned
// with Samples=0 and Confidence=0 so the stats table can show them with
// a "—" placeholder. Errors are logged and skipped — a corrupt row does
// not poison the whole table.
func (s *SQLiteConfidenceStore) WindowStats() []CategoryStats {
	if s == nil || s.db == nil {
		return nil
	}
	cutoff := time.Now().UTC().Add(-s.window)

	ctx, cancel := context.WithTimeout(context.Background(), confidenceOpTimeout)
	defer cancel()

	rows, err := s.db.QueryContext(ctx, `
		SELECT
		    category,
		    COUNT(*) AS samples,
		    COALESCE(AVG(CASE WHEN score >= ? THEN 1.0 ELSE 0.0 END), 0) AS confidence
		FROM routing_outcomes
		WHERE route = ? AND timestamp > ?
		GROUP BY category`,
		s.successScore, string(RouteLocal), cutoff)
	if err != nil {
		slog.Warn("confidence: window stats query", slog.Any("err", err))
		return nil
	}
	defer rows.Close()

	// Map from category name → stats. Missing categories get zeroed entries.
	stats := make(map[string]CategoryStats)
	for rows.Next() {
		var cs CategoryStats
		if err := rows.Scan(&cs.Category, &cs.Samples, &cs.Confidence); err != nil {
			slog.Warn("confidence: window stats scan", slog.Any("err", err))
			continue
		}
		stats[cs.Category] = cs
	}
	if err := rows.Err(); err != nil {
		slog.Warn("confidence: window stats rows", slog.Any("err", err))
	}

	// Emit every fixed category so empty ones appear with 0 samples.
	all := make([]CategoryStats, 0, len(categoryKeywords)+1)
	for _, kw := range categoryKeywords {
		if cs, ok := stats[kw.category]; ok {
			all = append(all, cs)
		} else {
			all = append(all, CategoryStats{Category: kw.category})
		}
	}
	// "other" is the fallback; include it last.
	if cs, ok := stats[CategoryOther]; ok {
		all = append(all, cs)
	} else {
		all = append(all, CategoryStats{Category: CategoryOther})
	}
	return all
}

// Close closes the underlying database. Safe to call multiple times.
func (s *SQLiteConfidenceStore) Close() error {
	if s == nil {
		return nil
	}
	s.closeOnce.Do(func() {
		if s.db != nil {
			s.closeErr = s.db.Close()
		}
	})
	return s.closeErr
}

// Compile-time guard: SQLiteConfidenceStore satisfies ConfidenceStore.
var _ ConfidenceStore = (*SQLiteConfidenceStore)(nil)

